import mne
import numpy as np
import os
from fractions import Fraction
from scipy.signal import firwin, resample_poly


def eeglab_resample(raw, sfreq, fc=0.9, df=0.2):
    """Resample like EEGLAB's pop_resample (Signal Processing Toolbox branch).

    Same anti-aliasing filter as EEGLAB (firfilt: Kaiser window, beta 5, ripple
    0.002), same edge padding, and the same rational ratio p/q. MNE's own
    raw.resample() derives its ratio from sample counts, which only matches
    EEGLAB when the recording length divides evenly, so it is not used here.
    """
    ratio = Fraction(sfreq / raw.info['sfreq']).limit_denominator(10**6)
    p, q = ratio.numerator, ratio.denominator
    fc, df = fc / max(p, q), df / max(p, q)
    m = int(np.ceil((1 + (-20 * np.log10(0.002) - 8) / (2.285 * 2 * np.pi * df / 2)) / 2) * 2)
    b = firwin(m + 1, fc, window=('kaiser', 5))  # resample_poly applies EEGLAB's gain p
    npad = int(np.ceil((m / 2) / q) * q)
    x = np.pad(raw.get_data(), ((0, 0), (npad, npad)), mode='edge')
    y = resample_poly(x, p, q, axis=-1, window=b, padtype='constant')
    cut = npad * p // q
    y = y[:, cut:y.shape[1] - cut]
    new = mne.io.RawArray(y, mne.create_info(raw.ch_names, sfreq, raw.get_channel_types()),
                          verbose=False)
    new.set_meas_date(raw.info['meas_date'])
    montage = raw.get_montage()
    if montage is not None:
        new.set_montage(montage, on_missing='ignore')
    new.info['bads'] = list(raw.info['bads'])
    if raw.info['projs']:
        new.add_proj(raw.info['projs'])
    new.set_annotations(raw.annotations)
    return new


# --- L2: datapath = '/data/study'  [exact]
datapath = '/data/study'

# --- L3: outpath = fullfile(datapath, 'derivatives')  [exact]
outpath = os.path.join(datapath, 'derivatives')

# --- L4: subjects = {'sub01', 'sub02', 'sub03'}  [exact]
subjects = ['sub01', 'sub02', 'sub03']

# --- L6: for s = 1:length(subjects)  [exact]
for s in range(1, len(subjects) + 1):
    # --- L7: EEG = pop_loadset('filename', [subjects{s} '.set'], 'filepath', datapath)  [exact]
    raw = mne.io.read_raw_eeglab(os.path.join(datapath, subjects[s - 1] + '.set'), preload=True)

    # --- L8: EEG = pop_select(EEG, 'nochannel', {'HEOG' 'VEOG'})  [exact]
    raw.drop_channels(['HEOG', 'VEOG'])

    # --- L9: if EEG.srate > 250  [exact]
    if raw.info['sfreq'] > 250:
        # --- L10: EEG = pop_resample(EEG, 250)  [exact]
        raw = eeglab_resample(raw, 250)

    # --- L12: EEG = pop_eegfiltnew(EEG, 'locutoff', 0.1, 'hicutoff', 30)  [exact]
    # Reproduce pop_eegfiltnew's design: one Hamming windowed-sinc filter whose order
    # comes from the transition band, rounded up to even (firfilt plugin rules).
    _fs = raw.info['sfreq']
    _df = min(max(0.1 * 0.25, 2), min(0.1, _fs / 2 - 30))  # EEGLAB's default transition band (Hz)
    _order = int(np.ceil(3.3 / (_df / _fs) / 2) * 2)
    _df = 3.3 / _order * _fs  # transition band EEGLAB actually uses
    raw.filter(l_freq=0.1, h_freq=30, l_trans_bandwidth=_df, h_trans_bandwidth=_df, filter_length=_order + 1, method='fir', fir_design='firwin', fir_window='hamming', phase='zero', pad='edge', skip_by_annotation=('edge', 'bad_acq_skip', 'boundary'))

    # --- L13: EEG = pop_reref(EEG, [])  [exact]
    raw.set_eeg_reference('average', projection=False)

    # --- L14: EEG = pop_epoch(EEG, {'S  1' 'S  2'}, [-0.2 0.8])  [exact]
    # Reproduce EEGLAB's epoch.m: limits rounded to whole samples (MATLAB rounding),
    # last sample excluded, and each event placed at floor(latency) like EEGLAB.
    _fs = raw.info['sfreq']
    _mround = lambda x: int(np.sign(x) * np.floor(abs(x) + 0.5))
    _s0, _s1 = _mround(-0.2 * _fs), _mround(0.8 * _fs - 1)
    _ann = raw.annotations
    _t0 = 0.0 if _ann.orig_time is None else raw.first_time
    event_id = {d: i + 1 for i, d in enumerate(dict.fromkeys(d for d in _ann.description if d in ['S  1', 'S  2']))}
    events = np.array([[int(np.floor((on - _t0) * _fs + 1e-6)) + raw.first_samp, 0, event_id[d]]
                       for on, d in zip(_ann.onset, _ann.description) if d in event_id],
                      dtype=int).reshape(-1, 3)
    epochs = mne.Epochs(raw, events, event_id=event_id, tmin=_s0 / _fs, tmax=_s1 / _fs,
                        baseline=None, preload=True)
    # EEGLAB discards epochs that span a data discontinuity ('boundary' event)
    _bnd = [int(round((on - _t0) * _fs)) + raw.first_samp
            for on, d in zip(_ann.onset, _ann.description) if d == 'boundary']
    if _bnd:
        epochs.drop([i for i, e in enumerate(epochs.events[:, 0])
                     if any(e + _s0 < b <= e + _s1 for b in _bnd)], reason='boundary')

    # --- L15: EEG = pop_rmbase(EEG, [-200 0])  [exact]
    epochs.apply_baseline((-0.2, 0.0))

    # --- L16: EEG = pop_saveset(EEG, 'filename', sprintf('%s_epo.set', subjects{s}), 'filepath', outpath)  [exact]
    epochs.save(os.path.join(outpath, os.path.splitext(('%s_epo.set' % (subjects[s - 1],)))[0] + '-epo.fif'), overwrite=True)
